.modelBar {
display: flex;
flex-wrap: wrap;
text-align: center;
justify-content: center;
}
.modelBar .modelBarItem {
width: 16.666667%;
padding: 5px 10px;
}
@media (max-width: 1199px) {
.modelBar {
justify-content: center;
}
.modelBar .modelBarItem {
width: 25%;
padding: 5px 10px;
}
}
@media (max-width: 450px) {
.modelBar .modelBarItem {
width: 50%;
padding: 5px 10px;
}
}

